INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Services > Standards
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen alle Services in einem IT-System internationalen Standards entsprechen, um funktionsfähig zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionalität hängt nicht zwingend von Standards ab"}, {"text": "Ja", "correct": false, "because": "Standards sind oft optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Standards die Interoperabilität zwischen verschiedenen Services verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Standards fördern Kompatibilität"}, {"text": "Nein", "correct": false, "because": "Interoperabilität wird durch Standards unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, einen Service ohne Einhaltung von Standards sicher zu betreiben?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheit kann auch ohne Standards gewährleistet sein"}, {"text": "Nein", "correct": false, "because": "Standards helfen, sind aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Standards in der IT immer verbindlich und gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Standards sind freiwillig"}, {"text": "Ja", "correct": false, "because": "Verbindlichkeit hängt vom Kontext ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Services ohne standardisierte Protokolle effizient mit anderen Systemen kommunizieren?', 2, '[{"text": "Ja", "correct": true, "because": "Proprietäre Protokolle sind möglich"}, {"text": "Nein", "correct": false, "because": "Standards erleichtern, sind aber nicht zwingend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Standard wird häufig für die sichere Datenübertragung zwischen Services verwendet?', 3, '[{"text": "TLS", "correct": true, "because": "Verschlüsselt Kommunikation"}, {"text": "FTP", "correct": false, "because": "Unsicher und veraltet"}, {"text": "SNMP", "correct": false, "because": "Für Monitoring, nicht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll ist ein Standard für die Kommunikation zwischen Webservices?', 2, '[{"text": "SOAP", "correct": true, "because": "Standardisiert und weit verbreitet"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe"}, {"text": "SMTP", "correct": false, "because": "Für E-Mail"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Einhaltung von Standards bei Services?', 2, '[{"text": "Sicherstellung der Kompatibilität", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Reduktion der Entwicklungskosten", "correct": false, "because": "Nebenaspekt"}, {"text": "Erhöhung der Benutzerfreundlichkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard definiert oft die Struktur von IT-Service-Management-Prozessen?', 3, '[{"text": "ITIL", "correct": true, "because": "Rahmenwerk für Service-Management"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement, nicht spezifisch IT"}, {"text": "IEEE 802.3", "correct": false, "because": "Für Ethernet, nicht Services"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch Missachtung von Standards bei Services entstehen?', 2, '[{"text": "Inkompatibilität mit anderen Systemen", "correct": true, "because": "Standards fördern Zusammenarbeit"}, {"text": "Schnellere Serviceausführung", "correct": false, "because": "Unrealistisch"}, {"text": "Geringere Wartungsanforderungen", "correct": false, "because": "Eher umgekehrt"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Standards sind für IT-Services relevant?', 4, '[{"text": "ISO/IEC 27001", "correct": true, "because": "Informationssicherheit"}, {"text": "ITIL", "correct": true, "because": "Service-Management"}, {"text": "ISO/IEC 20000", "correct": true, "because": "IT-Service-Management"}, {"text": "ISO 14001", "correct": false, "because": "Umweltmanagement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einhaltung von Standards bei Services?', 3, '[{"text": "Verbesserte Interoperabilität", "correct": true, "because": "Kompatibilität mit anderen Systemen"}, {"text": "Höhere Sicherheit", "correct": true, "because": "Standards definieren Best Practices"}, {"text": "Vereinfachte Wartung", "correct": true, "because": "Einheitliche Prozesse"}, {"text": "Geringere Hardwareanforderungen", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind standardisiert für die Kommunikation von Services?', 4, '[{"text": "HTTP", "correct": true, "because": "Basis für Webdienste"}, {"text": "MQTT", "correct": true, "because": "Für IoT-Services"}, {"text": "REST", "correct": true, "because": "API-Kommunikation"}, {"text": "VLAN", "correct": false, "because": "Netzwerktechnik, kein Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch das Ignorieren von Standards?', 3, '[{"text": "Sicherheitslücken", "correct": true, "because": "Fehlende Best Practices"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Schwierige Integration"}, {"text": "Höhere Betriebskosten", "correct": true, "because": "Ineffiziente Prozesse"}, {"text": "Schnellere Implementierung", "correct": false, "because": "Eher Verzögerungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden durch Standards bei Services geregelt?', 3, '[{"text": "Sicherheitsanforderungen", "correct": true, "because": "Schutzmaßnahmen"}, {"text": "Kommunikationsprotokolle", "correct": true, "because": "Datenfluss"}, {"text": "Servicequalität", "correct": true, "because": "Leistungsstandards"}, {"text": "Bürogestaltung", "correct": false, "because": "Nicht relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Standards wie ITIL verbessern die Prozessqualität. b) Alle Standards sind für jedes IT-System zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ITIL ja, Standards optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Standards können die Entwicklungskosten erhöhen. b) Standards garantieren immer eine fehlerfreie Implementation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, Fehlerfreiheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) HTTP ist ein Standardprotokoll für Webservices. b) Standards sind nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "HTTP ja, Standards für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Standards können die Zusammenarbeit zwischen Services fördern. b) Proprietäre Lösungen sind immer standardkonform.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zusammenarbeit ja, Proprietäres oft nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ISO/IEC 27001 definiert Sicherheitsstandards für Services. b) Standards ändern sich nie nach ihrer Veröffentlichung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, Standards entwickeln sich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

